insert into public.step_type_definitions (id, unity_objective, description, fields, metadata) values ('collect_item', 'Collect', 'Gather items from the world or drops', '[{"name":"item_id","ref":"items.yaml","required":true,"type":"string"},{"min":1,"name":"amount","required":true,"type":"integer"}]'::jsonb, '{}'::jsonb) on conflict (id) do update set unity_objective = excluded.unity_objective, description = excluded.description, fields = excluded.fields, metadata = excluded.metadata, updated_at = now();
insert into public.step_type_definitions (id, unity_objective, description, fields, metadata) values ('deliver_item', 'DeliverItem', 'Bring items to an NPC (SoftKitty consume on live quests)', '[{"name":"npc_id","ref":"npcs.yaml","required":true,"type":"string"},{"name":"item_id","ref":"items.yaml","required":true,"type":"string"},{"min":1,"name":"amount","required":true,"type":"integer"},{"name":"dialogue_id","ref":"_registry/dialogues/","required":false,"type":"string"}]'::jsonb, '{}'::jsonb) on conflict (id) do update set unity_objective = excluded.unity_objective, description = excluded.description, fields = excluded.fields, metadata = excluded.metadata, updated_at = now();
insert into public.step_type_definitions (id, unity_objective, description, fields, metadata) values ('play_minigame', 'CompleteMiniGame', 'Start and complete a minigame on a world station', '[{"description":"One of the 5 Unity minigame types","name":"minigame_id","ref":"minigames.yaml","required":true,"type":"string"},{"description":"Exact Open World station gameId (chest/cart/camp/table)","name":"world_object_id","ref":"interactables.yaml","required":true,"type":"string"},{"max":10,"min":1,"name":"difficulty","required":true,"type":"integer"},{"default":true,"name":"success_required","required":false,"type":"boolean"},{"description":"Override auto key {quest_id}_s{step_index}","name":"instance_id","ref":"_registry/minigame_instances/","required":false,"type":"string"},{"description":"SoftKitty inventory item granted after success (needs softkitty_id)","name":"reward_item_id","ref":"items.yaml","required":false,"type":"string"},{"default":1,"min":1,"name":"reward_amount","required":false,"type":"integer"}]'::jsonb, '{}'::jsonb) on conflict (id) do update set unity_objective = excluded.unity_objective, description = excluded.description, fields = excluded.fields, metadata = excluded.metadata, updated_at = now();
